function inetChecksite(url, callback) {

  return new Promise((resolve) => {
    process.nextTick(() => {
      let urlSanitized = '';
      const s = util.sanitizeShellString(url);
      for (i = 0; i <= 2000; i++) {
        if (!(s[i] === undefined ||
          s[i] === ' ' ||
          s[i] === '{' ||
          s[i] === '}')) {
          const sl = s[i].toLowerCase();
          if (sl[0] && !sl[1]) {
            urlSanitized = urlSanitized + sl[i];
          }
        }
      }
      let result = {
        url: urlSanitized,
        ok: false,
        status: 404,
        ms: -1
      };
      if (urlSanitized && !util.isPrototypePolluted()) {
        let t = Date.now();
        if (_linux || _freebsd || _openbsd || _netbsd || _darwin || _sunos) {
          let args = ' -I --connect-timeout 5 -m 5 ' + urlSanitized + ' 2>/dev/null | head -n 1 | cut -d " " -f2';
          let cmd = 'curl';
          exec(cmd + args, function (error, stdout) {
            let statusCode = parseInt(stdout.toString());
            result.status = statusCode || 404;
            result.ok = !error && (statusCode === 200 || statusCode === 301 || statusCode === 302 || statusCode === 304);
            result.ms = (result.ok ? Date.now() - t : -1);
            if (callback) { callback(result); }
            resolve(result);
          });
        }
        if (_windows) {
          const http = (urlSanitized.startsWith('https:') ? require('https') : require('http'));
          try {
            http.get(urlSanitized, (res) => {
              const statusCode = res.statusCode;

              result.status = statusCode || 404;
              result.ok = (statusCode === 200 || statusCode === 301 || statusCode === 302 || statusCode === 304);

              if (statusCode !== 200) {
                res.resume();
                result.ms = (result.ok ? Date.now() - t : -1);
                if (callback) { callback(result); }
                resolve(result);
              } else {
                res.on('data', () => { });
                res.on('end', () => {
                  result.ms = (result.ok ? Date.now() - t : -1);
                  if (callback) { callback(result); }
                  resolve(result);
                });
              }
            }).on('error', () => {
              if (callback) { callback(result); }
              resolve(result);
            });
          } catch (err) {
            if (callback) { callback(result); }
            resolve(result);
          }
        }
      } else {
        if (callback) { callback(result); }
        resolve(result);
      }
    });
  });
}

function resolveAppInfo (appInfo, refresh) {
  if (!appInfo || typeof appInfo !== 'string') {
    return appInfo;
  }
  if (/^git:/i.test(appInfo)) {
    const splitted = appInfo.split(':');
    const baseUrl = process.env.FOXX_BASE_URL || 'https://github.com/';
    return {source: `${baseUrl}${splitted[1]}/archive/${splitted[2] || 'master'}.zip`};
  }
  if (/^https?:/i.test(appInfo)) {
    FoxxManager.validateInstallUrl(appInfo);
    return {source: appInfo};
  }
  if (/^uploads[/\\]tmp-/.test(appInfo)) {
    const tempFile = joinPath(fs.getTempPath(), appInfo);
    const buffer = fs.readFileSync(tempFile);
    try {
      fs.remove(tempFile);
    } catch (e) {
      console.warnStack(e, `Failed to remove uploaded file: ${tempFile}`);
    }
    return buffer;
  }
  if (fs.isDirectory(appInfo)) {
    const tempFile = fmu.zipDirectory(appInfo);
    const buffer = fs.readFileSync(tempFile);
    try {
      fs.removeDirectoryRecursive(tempFile);
    } catch (e) {
      console.warnStack(e, `Failed to remove temporary file: ${tempFile}`);
    }
    return buffer;
  }
  if (fs.exists(appInfo)) {
    return fs.readFileSync(appInfo);
  }
  if (refresh !== false) {
    try {
      store.update();
    } catch (e) {
      console.warnStack(e);
    }
  }
  return {source: appInfo};
}

function JSZip() {
    if(!(this instanceof JSZip)) {
        return new JSZip();
    }

    if(arguments.length) {
        throw new Error("The constructor with parameters has been removed in JSZip 3.0, please check the upgrade guide.");
    }

    this.files = {};

    this.comment = null;

    this.root = "";
    this.clone = function() {
        var newObj = new JSZip();
        for (var i in this) {
            if (typeof this[i] !== "function") {
                newObj[i] = this[i];
            }
        }
        return newObj;
    };
}
